import React, { useState, useEffect, useContext } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order3.jpg";

const UpdateOrder = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const { setOrdersChanged } = useContext(OrderContext);

  useEffect(() => {
    if (id) {
      axios
        .get(`http://localhost:5000/orders/${id}`)
        .then((res) => {
          if (res.data) {
            setOrderData(res.data);
          } else {
            setError("Order not found.");
          }
          setLoading(false);
        })
        .catch((err) => {
          console.error("Error fetching order data:", err);
          setError("Failed to fetch order data.");
          setLoading(false);
        });
    }
  }, [id]);

  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  const updateOrder = (e) => {
    e.preventDefault();

    axios
      .put(`http://localhost:5000/orders/${id}`, orderData)
      .then(() => {
        alert("Order Updated Successfully");
        
        // Trigger context update to refresh order list
        setOrdersChanged((prev) => !prev);

        navigate("/all-orders");
      })
      .catch((err) => {
        alert("Error Updating Order");
        console.error(err);
      });
  };

  const handleBackToOrders = () => {
    navigate("/all-orders");
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#f0f0f0",
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        backgroundBlendMode: "multiply",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.7)",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "100%",
          maxWidth: "600px",
          boxSizing: "border-box",
        }}
      >
        <h1 style={{ color: "#8B0000", fontWeight: "bold", textAlign: "center", marginBottom: "20px" }}>
          Update Order
        </h1>
        <form onSubmit={updateOrder} style={{ width: "100%" }}>
          {["firstName", "lastName", "email", "phoneNumber", "address", "city", "orderId", "specialInstructions", "pickupTime", "orderStatus"].map(
            (field) => (
              <div key={field} style={{ marginBottom: "15px" }}>
                <label htmlFor={field} style={{ display: "block", fontWeight: "bold" }}>
                  {field.replace(/([A-Z])/g, " $1").trim()}
                </label>
                <input
                  type="text"
                  id={field}
                  name={field}
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "5px",
                    boxSizing: "border-box",
                  }}
                  placeholder={`Enter ${field}`}
                  value={orderData[field]}
                  onChange={handleChange}
                />
              </div>
            )
          )}
          <button
            type="submit"
            style={{
              backgroundColor: "#b30000",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "16px",
              marginBottom: "10px",
            }}
          >
            Update Order
          </button>
        </form>
        <div style={{ display: "flex", justifyContent: "center" }}>
          <button
            onClick={handleBackToOrders}
            style={{
              backgroundColor: "#b30000",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "16px",
              width: "30%",
              marginTop: "10px",
            }}
          >
            Back to Orders
          </button>
        </div>
      </div>
    </div>
  );
};

export default UpdateOrder;
